tool_input.command:
ssh calc "ls -l /opt/alpha-compute/bin/alpha-tk231-pgo | cut -c1-60; install -d -m 700 /etc/alpha-launch && [ -s /etc/alpha-launch/token ] || (head -c 32 /dev/urandom | base64 | tr -d '/+=\n' > /etc/alpha-launch/token); chmod 600 /etc/alpha-launch/token; cp /opt/alpha-launch/tools/launch/alpha-launch.service /etc/systemd/system/ && systemctl daemon-reload && systemctl enable --now alpha-launch; sleep 2; systemctl is-active alpha-launch; ss -ltn | grep 8791"
$t = (ssh calc "cat /etc/alpha-launch/token").Trim()
$base = "http://89.163.242.211:8791"
foreach ($u in @("/$t/", "/$t/api/status", "/", "/api/meta", "/wrong/")) {
  try { $r = Invoke-WebRequest -Uri "$base$u" -UseBasicParsing -TimeoutSec 15; "$($u -replace [regex]::Escape($t),'<token>') -> $($r.StatusCode) $($r.RawContentLength)" } catch { "$($u -replace [regex]::Escape($t),'<token>') -> $($_.Exception.Response.StatusCode.value__)" }
}
try { Invoke-WebRequest -Uri "$base/api/submit" -Method Post -Body '{}' -UseBasicParsing | Out-Null } catch { "POST /api/submit -> $($_.Exception.Response.StatusCode.value__)" }
